TALK_SCHEMA = 1
SLIDE_KINDS = ('idea', 'pause', 'questions', 'recap', 'primer', 'board', 'timeline', 'code')
ASK_KINDS = ('choice', 'order', 'words', 'scale', 'none')
BEATS = ('passage', 'figure', 'demo', 'ask')
